#include <cstdio>
#include <iostream>
#include <algorithm>
#include <cstring> // Include for memset

using namespace std;

int minix(int a, int b, int c) {
    return std::min({a, b, c}); // Using std::min with initializer list for better performance
}

int main() {
    int n;
    int masu[1002][1002];
    int ura[1002][1002];
    char str[1002];

    while (true) {
        memset(masu, 0, sizeof(masu)); // Using memset for efficient zero-initialization

        scanf("%d", &n);
        if (n == 0) {
            break;
        }

        for (int i = 1; i <= n; i++) {
            scanf("%s", str);
            for (int j = 1; j <= n; j++) {
                ura[i][j] = (str[j - 1] == '.') ? 0 : 1; // Simplified the conditional
            }
        }

        int maxi = 0;
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (ura[i][j] == 0) {
                    masu[i][j] = minix(masu[i - 1][j], masu[i][j - 1], masu[i - 1][j - 1]) + 1;
                    maxi = max(masu[i][j], maxi);
                }
            }
        }

        printf("%d\n", maxi);
    }
}

