#include <cstdio>
#include <iostream>
#include <algorithm>
#include <cstring>
#include <vector>

using namespace std;

int minix(int a, int b, int c) {
    return min({a, b, c});
}

int main() {
    int n;
    while (true) {
        scanf("%d", &n);
        if (n == 0) {
            break;
        }

        vector<int> masu(n * n, 0); // Single vector for masu
        vector<int> ura(n * n, 0);  // Single vector for ura

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                char c;
                scanf(" %c", &c); // Read character directly into variable
                ura[i * n + j] = (c == '.') ? 0 : 1; // Flattened indexing
            }
        }

        int maxi = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (ura[i * n + j] == 0) {
                    masu[i * n + j] = minix(
                        (i > 0 ? masu[(i - 1) * n + j] : 0), 
                        (j > 0 ? masu[i * n + (j - 1)] : 0), 
                        (i > 0 && j > 0 ? masu[(i - 1) * n + (j - 1)] : 0)
                    ) + 1;
                    maxi = max(masu[i * n + j], maxi);
                }
            }
        }

        printf("%d\n", maxi);
    }
}

